package com.enterprise.siem.soar;
import com.enterprise.siem.model.*; import com.enterprise.siem.security.SecurityAuditLogger; import com.enterprise.siem.util.SIEMMetrics; import org.slf4j.*;
public final class ResponseManager { private static final Logger log=LoggerFactory.getLogger(ResponseManager.class); private final boolean dryRun; private final ProcessExecutor executor; private final SecurityAuditLogger audit; private final SIEMMetrics metrics; public ResponseManager(boolean dryRun, ProcessExecutor executor, SecurityAuditLogger audit){this(dryRun,executor,audit,null);} public ResponseManager(boolean dryRun, ProcessExecutor executor, SecurityAuditLogger audit, SIEMMetrics metrics){this.dryRun=dryRun;this.executor=executor;this.audit=audit;this.metrics=metrics;}
 public void respond(Incident incident, Alert alert){ ResponseAction action=incident.severity()==Severity.CRITICAL?ResponseAction.SIMULATE_ISOLATION:ResponseAction.LOG_INCIDENT; String result; try { executor.execute(action,dryRun); result=dryRun?"DRY_RUN":"EXECUTED"; if(metrics!=null)metrics.soarActions.increment(); log.info("SOAR {} for incident {}",result,incident.incidentId()); } catch(Exception e){result="ERROR";if(metrics!=null)metrics.soarFailures.increment();log.error("SOAR action failed",e);} if(!audit.log(incident,alert,action.name(),result)){if(metrics!=null)metrics.auditFailures.increment();log.error("Unable to write SOAR audit for incident {}",incident.incidentId());} }
}
